import{_ as n,o as i,c as e,a2 as t}from"./chunks/framework.CqpfiAoK.js";const o=JSON.parse('{"title":"Hukum Jaminan Pendidikan","description":"","frontmatter":{},"headers":[],"relativePath":"id/0043-教育保障法.md","filePath":"id/0043-教育保障法.md"}'),d={name:"id/0043-教育保障法.md"};function u(r,a,s,k,m,l){return i(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="hukum-jaminan-pendidikan" tabindex="-1">Hukum Jaminan Pendidikan <a class="header-anchor" href="#hukum-jaminan-pendidikan" aria-label="Permalink to &quot;Hukum Jaminan Pendidikan&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Proyek</th><th>Konten</th></tr></thead><tbody><tr><td>Nomor dokumen</td><td>43</td></tr><tr><td>Modul</td><td>Sistem Hukum dan Kerangka Tata Kelola</td></tr><tr><td>Kata kunci utama</td><td>Hak Pendidikan, Pendidikan Simbiosis, Pewarisan Kultivasi, Pembelajaran Sepanjang Hayat, Keadilan Pendidikan</td></tr></tbody></table><h2 id="i-tujuan-legislasi-dan-prinsip-dasar" tabindex="-1">I. Tujuan Legislasi dan Prinsip Dasar <a class="header-anchor" href="#i-tujuan-legislasi-dan-prinsip-dasar" aria-label="Permalink to &quot;I. Tujuan Legislasi dan Prinsip Dasar&quot;">​</a></h2><p>《Hukum Jaminan Pendidikan》 adalah salah satu dari lima hukum pendukung peradaban simbiosis jangkar, bertujuan untuk menjamin hak pendidikan semua makhluk di dalam Hengyuanzhou, membangun sistem pendidikan dengan konsep inti &quot;evolusi simbiosis&quot;, dan menyediakan dukungan pengetahuan serta bakat untuk kemajuan bersama semua ras.</p><p>Hukum ini menetapkan prinsip dasar berikut:</p><table tabindex="0"><thead><tr><th>Prinsip</th><th>Isi</th></tr></thead><tbody><tr><td>Prinsip Keadilan Pendidikan</td><td>Semua makhluk, tanpa memandang ras, tingkat kultivasi, asal-usul, menikmati kesempatan pendidikan yang sama</td></tr><tr><td>Prinsip Pengajaran Sesuai Bakat</td><td>Menghormati perbedaan bakat dan pilihan jalur evolusi setiap makhluk, menyediakan rencana pendidikan yang dipersonalisasi</td></tr><tr><td>Prinsip Kesatuan Pengetahuan dan Tindakan</td><td>Menggabungkan pengetahuan teoretis dan kultivasi praktis, menentang pendidikan percakapan kosong yang terlepas dari realitas</td></tr><tr><td>Prinsip Keterbukaan dan Berbagi</td><td>Sumber daya pendidikan terbuka untuk seluruh masyarakat, metode dasar dari tiga ratus sistem kultivasi asal diajarkan secara gratis</td></tr><tr><td>Prinsip Pembelajaran Sepanjang Hayat</td><td>Pendidikan berlangsung sepanjang proses kehidupan, mendukung pembelajaran berkelanjutan dan peningkatan kemampuan di semua tahap</td></tr><tr><td>Prinsip Keragaman Budaya</td><td>Menghormati tradisi budaya setiap ras, mendorong pertukaran dan saling belajar antar budaya</td></tr></tbody></table><h2 id="ii-jaminan-hukum-hak-pendidikan" tabindex="-1">II. Jaminan Hukum Hak Pendidikan <a class="header-anchor" href="#ii-jaminan-hukum-hak-pendidikan" aria-label="Permalink to &quot;II. Jaminan Hukum Hak Pendidikan&quot;">​</a></h2><p>Hukum ini menetapkan dengan jelas bahwa hak pendidikan adalah hak dasar yang diberikan kepada setiap makhluk oleh Konstitusi Simbiosis, dan negara serta peradaban memiliki kewajiban untuk menjamin realisasi hak ini:</p><ol><li><strong>Pendidikan Dasar Gratis</strong>: Semua makhluk berhak menerima pendidikan dasar gratis, termasuk pengetahuan umum, metode dasar kultivasi, konsep peradaban simbiosis, dll., dengan durasi enam hingga dua belas tahun, disesuaikan sesuai siklus perkembangan ras.</li><li><strong>Pengenalan Kultivasi Gratis</strong>: Metode dasar dari tiga ratus sistem kultivasi asal alam semesta terbuka gratis untuk semua makhluk, tidak ada organisasi atau individu yang boleh menguasai metode dasar kultivasi sebagai milik pribadi dan mengajarkannya dengan biaya.</li><li><strong>Kesetaraan Kesempatan Pendidikan Lanjutan</strong>: Lembaga pendidikan di semua tingkatan dan jenis tidak boleh menetapkan syarat diskriminatif seperti ras, tingkat kultivasi, asal-usul, dll. dalam penerimaan, dan kriteria penerimaan harus terbuka dan transparan.</li><li><strong>Jaminan Pendidikan Khusus</strong>: Menyediakan sumber daya pendidikan khusus yang adaptif dan dukungan pendidikan jarak jauh untuk kelompok seperti makhluk cacat, makhluk ras lain, makhluk dari bidang terpencil, dll.</li><li><strong>Sistem Bantuan Pendidikan</strong>: Memberikan beasiswa, penghargaan prestasi, dan pinjaman tanpa bunga kepada pelajar dengan kesulitan keuangan, memastikan tidak kehilangan kesempatan pendidikan karena alasan ekonomi.</li></ol><h2 id="iii-struktur-sistem-pendidikan" tabindex="-1">III. Struktur Sistem Pendidikan <a class="header-anchor" href="#iii-struktur-sistem-pendidikan" aria-label="Permalink to &quot;III. Struktur Sistem Pendidikan&quot;">​</a></h2><p>Sistem pendidikan peradaban simbiosis jangkar dibagi menjadi empat tingkatan, yang saling terhubung secara organik:</p><table tabindex="0"><thead><tr><th>Tingkatan</th><th>Nama</th><th>Tujuan</th><th>Durasi</th></tr></thead><tbody><tr><td>Tingkatan pertama</td><td>Pendidikan Awal</td><td>Menumbuhkan kemampuan kognitif dasar dan kesadaran simbiosis, mengajarkan metode dasar kultivasi</td><td>3-6 tahun</td></tr><tr><td>Tingkatan kedua</td><td>Pendidikan Dasar</td><td>Pembelajaran sistematis pengetahuan umum dan teori kultivasi, menemukan arah bakat individu</td><td>6-9 tahun</td></tr><tr><td>Tingkatan ketiga</td><td>Pendidikan Profesional</td><td>Pembelajaran mendalam dan praktik dalam sistem kultivasi atau bidang profesional yang dipilih</td><td>3-10 tahun</td></tr><tr><td>Tingkatan keempat</td><td>Studi Lanjutan</td><td>Eksplorasi terdepan dan studi inovatif untuk kultivator tingkat lanjut dan peneliti</td><td>Tidak terbatas</td></tr></tbody></table><p>Selain itu, &quot;Sistem Jaringan Mentor&quot; didirikan: kultivator yang mencapai tingkat kultivasi tertentu memiliki kewajiban untuk membimbing kultivator pemula dalam batas kemampuannya, dan kontribusi bimbingan dihitung dalam jumlah kontribusi mekanisme kontrak produksi bersama, menikmati distribusi sumber daya yang sesuai.</p><h2 id="iv-lembaga-pendidikan-dan-guru" tabindex="-1">IV. Lembaga Pendidikan dan Guru <a class="header-anchor" href="#iv-lembaga-pendidikan-dan-guru" aria-label="Permalink to &quot;IV. Lembaga Pendidikan dan Guru&quot;">​</a></h2><ul><li><strong>Lembaga Pendidikan Publik</strong>: Didirikan oleh negara atau komunitas peradaban, bertanggung jawab atas pendidikan dasar gratis dan layanan pendidikan publik, dengan pendanaan dijamin oleh akumulasi publik.</li><li><strong>Lembaga Pendidikan Swasta</strong>: Didirikan oleh kekuatan sosial sesuai hukum, dapat memungut biaya yang wajar, tetapi harus menerima pengawasan dari departemen pendidikan yang berwenang, dan tidak boleh melakukan promosi palsu atau memungut biaya predator.</li><li><strong>Sekte Kultivasi</strong>: Organisasi kultivasi tradisional setelah pendaftaran dapat beroperasi sebagai lembaga pendidikan profesional, harus mematuhi ketentuan hukum pendidikan, dan tidak boleh menutup serta memonopoli sumber daya kultivasi.</li><li><strong>Hak dan Kewajiban Guru</strong>: Guru menikmati hak seperti kebebasan akademik, imbalan yang wajar, pelatihan profesional, dll., dan pada saat yang sama memiliki kewajiban untuk mengajar dan mendidik, menjadi teladan, menjaga privasi siswa, dll.</li></ul><h2 id="v-konten-pendidikan-dan-standar-kurikulum" tabindex="-1">V. Konten Pendidikan dan Standar Kurikulum <a class="header-anchor" href="#v-konten-pendidikan-dan-standar-kurikulum" aria-label="Permalink to &quot;V. Konten Pendidikan dan Standar Kurikulum&quot;">​</a></h2><p>Konten pendidikan harus memenuhi persyaratan berikut:</p><ol><li>Termasuk konsep inti peradaban simbiosis dan pendidikan anti-predator, menumbuhkan kesadaran simbiosis pelajar.</li><li>Termasuk teori dasar dan metode pengenalan dari tiga ratus sistem kultivasi asal.</li><li>Termasuk pengetahuan ilmiah umum seperti hukum alam semesta, pengetahuan bidang, ilmu kehidupan, dll.</li><li>Termasuk sejarah dan budaya semua ras, mempromosikan saling pengertian dan penghormatan antar ras.</li><li>Termasuk环节 kultivasi praktis dan layanan sosial, menumbuhkan kemampuan menyatukan pengetahuan dan tindakan.</li><li>Melarang penyebaran konsep kultivasi predator dan ide diskriminatif.</li></ol><h2 id="vi-tanggung-jawab-hukum" tabindex="-1">VI. Tanggung Jawab Hukum <a class="header-anchor" href="#vi-tanggung-jawab-hukum" aria-label="Permalink to &quot;VI. Tanggung Jawab Hukum&quot;">​</a></h2><p>Kegiatan yang melanggar ketentuan hukum ini menanggung tanggung jawab berikut sesuai tingkat keparahan pelanggaran:</p><ul><li>Menolak atau menghambat makhluk usia sekolah menerima pendidikan wajib, diperintahkan untuk memperbaiki dan dihukum.</li><li>Lembaga pendidikan yang memungut biaya ilegal atau melakukan promosi palsu, diperintahkan mengembalikan biaya dan didenda, dalam kasus parah izin operasional dicabut.</li><li>Guru yang melakukan hukuman fisik atau mendiskriminasi siswa, dihukum, dalam kasus parah kualifikasi guru dicabut dan dituntut tanggung jawab hukum.</li><li>Menguasai sumber daya kultivasi publik sebagai milik pribadi, memonopoli dan memungut biaya, keuntungan ilegal disita dan didenda.</li></ul><h2 id="penutup" tabindex="-1">Penutup <a class="header-anchor" href="#penutup" aria-label="Permalink to &quot;Penutup&quot;">​</a></h2><p>《Hukum Jaminan Pendidikan》 adalah praktik pendidikan dari konsep &quot;setiap orang memiliki jalan&quot; peradaban simbiosis jangkar. Dengan menjamin hak pendidikan, membangun sistem pendidikan berjenjang, dan membuka sumber daya kultivasi, ia memastikan setiap makhluk dapat memperoleh jalur evolusi yang sesuai dengan dirinya, menyediakan pengetahuan dan bakat secara terus-menerus untuk kemajuan bersama semua ras.</p><h2 id="dokumen-terkait" tabindex="-1">Dokumen terkait <a class="header-anchor" href="#dokumen-terkait" aria-label="Permalink to &quot;Dokumen terkait&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Prinsip Umum Konstitusi Simbiosis)</li><li>37-共生教育体系 (Sistem Pendidikan Simbiosis)</li><li>10-三百套本源修炼体系总览 (Gambaran Umum Tiga Ratus Sistem Kultivasi Asal)</li><li>08-人人有路保障体系 (Sistem Jaminan Setiap Orang Memiliki Jalan)</li></ul>',25)])])}const g=n(d,[["render",u]]);export{o as __pageData,g as default};
